/** Checks 14/19: one row frame, the first visible name line; tolerance stays 0.5 px. */
const ROW_NAME_TOLERANCE = 0.5;

function validBox(box) {
  return Array.isArray(box) && box.length === 4 && box.every(Number.isFinite)
    && box[2] > 0 && box[3] > 0;
}

export function nameLineFrame(firstText) {
  if (!firstText || firstText.visible !== true || !String(firstText.text || '').trim()) return null;
  // New captures carry Range rects. Immutable legacy captures retain their recorded leaf box.
  // Never derive a name frame from the item, chip, or an inferred line height.
  const boxes = firstText.line_boxes === undefined ? [firstText.box] : firstText.line_boxes;
  if (!Array.isArray(boxes)) return null;
  const line = boxes.filter(validBox).sort((a, b) => a[1] - b[1] || a[0] - b[0])[0];
  return line ? { box: line, cy: line[1] + line[3] / 2,
    source: firstText.line_boxes === undefined ? 'legacy-leaf-box' : 'range-first-line' } : null;
}

export function judgeRowNameFrame(glyphCenterY, firstText) {
  const frame = nameLineFrame(firstText);
  if (!frame) return { ok: false, reason: 'missing visible name line (fail closed)' };
  if (!Number.isFinite(glyphCenterY)) return { ok: false, reason: 'missing measured logo glyph (fail closed)', frame };
  const offset = glyphCenterY - frame.cy;
  return { ok: Math.abs(offset) <= ROW_NAME_TOLERANCE, offset, frame,
    reason: `logo ${offset > 0 ? 'low' : 'high'} vs first name line by ${Math.abs(offset)} px (tolerance ${ROW_NAME_TOLERANCE} px)` };
}

lib/gate-b-shell-layout-checker.mjs:
/** Gate B restore-check: row logo chips vs capture frame (viewport or tab clip). */

const EPS = 0.5;

function normalizeCaptureFrame(frame = null) {
  if (!frame || typeof frame !== 'object') return null;
  const x = Number(frame.x) || 0;
  const y = Number(frame.y) || 0;
  const width = Number(frame.width);
  const height = Number(frame.height);
  if (!Number.isFinite(width) || !Number.isFinite(height) || width <= 0 || height <= 0) {
    return null;
  }
  return { x, y, width, height, right: x + width, bottom: y + height };
}

function normalizeChipRect(rect = null) {
  if (!rect || typeof rect !== 'object') return null;
  const left = Number(rect.left);
  const top = Number(rect.top);
  const right = Number(rect.right);
  const bottom = Number(rect.bottom);
  if (![left, top, right, bottom].every(Number.isFinite)) return null;
  if (right <= left || bottom <= top) return null;
  return { left, top, right, bottom, width: right - left, height: bottom - top };
}

/** @returns {'in_frame'|'clipped'|'off_frame'|'unknown'} */
export function chipCaptureClipRelation(chipRect, captureFrame) {
  const chip = normalizeChipRect(chipRect);
  const frame = normalizeCaptureFrame(captureFrame);
  if (!chip || !frame) return 'unknown';
  const fullyInside = chip.left >= frame.x - EPS
    && chip.top >= frame.y - EPS
    && chip.right <= frame.right + EPS
    && chip.bottom <= frame.bottom + EPS;
  if (fullyInside) return 'in_frame';
  const intersects = chip.right > frame.x + EPS
    && chip.left < frame.right - EPS
    && chip.bottom > frame.y + EPS
    && chip.top < frame.bottom - EPS;
  if (!intersects) return 'off_frame';
  return 'clipped';
}

export function isCaptureCoverageGap(chipRect, captureFrame) {
  const rel = chipCaptureClipRelation(chipRect, captureFrame);
  return rel === 'clipped' || rel === 'off_frame';
}

export function viewportCaptureFrame(width, height) {
  return { x: 0, y: 0, width: Number(width) || 0, height: Number(height) || 0 };
}

managing_dr_judge.py:
"""Gate B judgment inbox. The managing dr reads requests and supplies verdicts.

No model subprocess, paid fallback, or usage/reset dependency. A missing or
invalid receipt returns None so existing Gate B checks continue to fail closed.
"""
import datetime
import hashlib
import json
import os
from pathlib import Path
import tempfile

ROOT = os.path.expanduser("~/tsv-gateb/dr-description-judgments")
REVIEWERS = {"gpt", "claude-code", "grok", "dr-eggbot"}


def atomic_json(path, value):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(prefix=".judge-", dir=str(path.parent))
    try:
        with os.fdopen(fd, "w") as f:
            json.dump(value, f, indent=2, sort_keys=True)
            f.write("\n")
        os.replace(tmp, path)
    finally:
        if os.path.exists(tmp):
            os.unlink(tmp)


class ManagingDrJudgmentPending(RuntimeError):
    """No qualitative verdict yet; a harness pause, never a coder failure."""


class ManagingDrJudge:
    def __init__(self, cache_path=ROOT, cap=60, offline=False, usage=True):
        # cache_path names a receipt directory, never the old Haiku cache.
        self.root = Path(cache_path)
        self.cap, self.offline = cap, offline
        self.calls = self.hits = self.skipped = 0
        self.gate = "managing dr judgment required"
        self.context = "unbound"
        self.pending_keys = set()

    def bind_capture(self, cand_dir):
        # Bind to the actual captured text/geometry and fixture digest. Do not
        # export the manifest (it can contain a shared-trip access token).
        path = Path(cand_dir)
        regions = (path / "capture-regions.json").read_bytes()
        try:
            manifest = json.loads((path / "capture-manifest.json").read_text())
        except (OSError, ValueError):
            manifest = {}
        self.context = hashlib.sha256(regions + str(manifest.get("capture_fixture_sha256") or manifest.get("fixture_sha256") or "").encode()).hexdigest()

    def request(self, cat, name, price, text, rubric=None, scope=None, reviews=None, ask=None):
        body = {"schema": 1, "context": self.context, "cat": cat,
                "name": name, "price": price, "text": text,
                "rubric": rubric or self.rubrics.get(cat, ""),
                "scope": scope, "reviews": reviews or [], "ask": ask,
                "standard": "score 1-5; pass requires >=4 and non-generic; unchanged category rubric"}
        key = hashlib.sha256(json.dumps(body, sort_keys=True, ensure_ascii=False, separators=(",", ":")).encode()).hexdigest()
        return {"key": key, "input": body}

    @staticmethod
    def valid_receipt(receipt, request):
        if not isinstance(receipt, dict) or receipt.get("key") != request["key"] or receipt.get("input") != request["input"]:
            return False
        if receipt.get("reviewer") not in REVIEWERS or not str(receipt.get("reason") or "").strip():
            return False
        try:
            stamp = datetime.datetime.fromisoformat(receipt["reviewed_at"].replace("Z", "+00:00"))
            if stamp.tzinfo is None or stamp > datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(minutes=5):
                return False
        except (KeyError, TypeError, ValueError, AttributeError):
            return False
        value = receipt.get("verdict")
        return (isinstance(value, dict) and type(value.get("score")) is int and 1 <= value["score"] <= 5
                and type(value.get("generic")) is bool and isinstance(value.get("missing"), list)
                and all(isinstance(x, str) for x in value["missing"]))

    def judge(self, cat, name, price, text, rubric=None, scope=None, reviews=None, ask=None):
        request = self.request(cat, name, price, text, rubric, scope, reviews, ask)
        key = request["key"]
        try:
            receipt = json.loads((self.root / "verdicts" / (key + ".json")).read_text())
        except (OSError, ValueError):
            receipt = None
        if self.valid_receipt(receipt, request):
            self.hits += 1
            return dict(receipt["verdict"], cat=cat)
        if not self.offline and self.context != "unbound":
            atomic_json(self.root / "pending" / (key + ".json"), request)
            self.pending_keys.add(key)
        self.skipped += 1
        return None

